/** Return one deduplicated global-order list. Write a single import manifest. */
export function componentStylesheets(names) {
  if (!Array.isArray(names)) throw new TypeError('Component names must be an array');
  const selected = new Set(foundation);
  for (const name of names) {
    if (typeof name !== 'string' || !Object.hasOwn(entries, name)) throw new Error('Unknown component CSS entry: ' + String(name));
    entries[name].forEach(path => selected.add(path));
  }
  return order.filter(path => selected.has(path));
}
